Module new_module(const char* name, const char* path, const char* file) {
    Array a = ({ Array _a = arr_make(sizeof(int64_t)); _a; });
    Array b = ({ Array _a = arr_make(sizeof(int64_t)); _a; });
    Array v = ({ Array _a = arr_make(sizeof(int64_t)); _a; });
    return (Module){name, path, file, a, b, v};
}

Parser new_parser(Array toks) {
    return (Parser){toks, 0, false, false, 0, 0, "", 0};
}

Token p_peek(Parser* p) {
    return ((Token*)(p->toks).data)[p->pos];
}

Token p_peek_at(Parser* p, int64_t off) {
    int64_t i = (p->pos + off);
    if (i < p->toks.len) {
        return ((Token*)(p->toks).data)[i];
    }
    return ((Token*)(p->toks).data)[(p->toks.len - 1)];
}

Token p_prev(Parser* p) {
    return ((Token*)(p->toks).data)[(p->pos - 1)];
}

bool p_at_end(Parser* p) {
    return (p_peek(p).kind == TkEof);
}

bool p_check(Parser* p, TokKind k) {
    return (p_peek(p).kind == k);
}

Token p_advance(Parser* p) {
    if (!p_at_end(p)) {
        p->pos += 1;
    }
    return p_prev(p);
}

bool p_match(Parser* p, TokKind k) {
    if (p_check(p, k)) {
        p_advance(p);
        return true;
    }
    return false;
}

const char* tok_desc(Token t) {
    if (((t.kind == TkIdent) || (t.kind == TkInt)) || (t.kind == TkFloat)) {
        return str_concat(str_concat(str_concat(kind_name(t.kind), " '"), t.text), "'");
    }
    if (t.kind == TkString) {
        return "a string literal";
    }
    if (t.kind == TkChar) {
        return "a char literal";
    }
    if (((t.kind == TkNewline) || (t.kind == TkEof)) || (t.kind == TkError)) {
        return kind_name(t.kind);
    }
    return str_concat(str_concat("'", kind_name(t.kind)), "'");
}

void p_error(Parser* p, Token t, const char* msg) {
    if (!p->had_error) {
        p->err_line = t.line;
        p->err_col = t.col;
        p->err_msg = msg;
    }
    p->had_error = true;
}

void p_unexpected(Parser* p) {
    p_error(p, p_peek(p), str_concat("unexpected ", tok_desc(p_peek(p))));
}

Token p_expect(Parser* p, TokKind k) {
    if (p_check(p, k)) {
        return p_advance(p);
    }
    p_error(p, p_peek(p), str_concat(str_concat(str_concat("expected '", kind_name(k)), "', got "), tok_desc(p_peek(p))));
    return p_peek(p);
}

void skip_newlines(Parser* p) {
    while (p_check(p, TkNewline) || p_check(p, TkSemicolon)) {
        p_advance(p);
    }
}

TypeNode* parse_type(Parser* p) {
    Token nt = p_peek(p);
    TypeNode* t = new_type(TyNamed, nt.line, nt.col);
    t->name = p_expect(p, TkIdent).text;
    while (p_check(p, TkLBracket) || p_check(p, TkStar)) {
        if (p_check(p, TkLBracket)) {
            p_advance(p);
            TypeNode* arr = new_type(TyArray, t->line, t->col);
            if (p_check(p, TkIdent) && str_eq(p_peek(p).text, "dynamic")) {
                p_advance(p);
                arr->kind = TyDynArray;
            } else 
            if (p_check(p, TkInt)) {
                arr->kind = TyFixedArray;
                arr->size = p_advance(p).text;
            }
            p_expect(p, TkRBracket);
            arr->elem = t;
            t = arr;
        } else {
            p_advance(p);
            TypeNode* ptr = new_type(TyPointer, t->line, t->col);
            ptr->elem = t;
            t = ptr;
        }
    }
    return t;
}

int64_t skip_type_at(Parser* p, int64_t i) {
    if (((Token*)(p->toks).data)[i].kind != TkIdent) {
        return (0 - 1);
    }
    i += 1;
    while ((((Token*)(p->toks).data)[i].kind == TkLBracket) || (((Token*)(p->toks).data)[i].kind == TkStar)) {
        if (((Token*)(p->toks).data)[i].kind == TkStar) {
            i += 1;
        } else {
            i += 1;
            if (((Token*)(p->toks).data)[i].kind == TkInt) {
                i += 1;
            } else 
            if ((((Token*)(p->toks).data)[i].kind == TkIdent) && str_eq(((Token*)(p->toks).data)[i].text, "dynamic")) {
                i += 1;
            }
            if (((Token*)(p->toks).data)[i].kind != TkRBracket) {
                return (0 - 1);
            }
            i += 1;
        }
    }
    return i;
}

bool looks_like_typed_decl(Parser* p) {
    int64_t i = skip_type_at(p, p->pos);
    if (i < 0) {
        return false;
    }
    return (((Token*)(p->toks).data)[i].kind == TkIdent);
}

bool looks_like_func(Parser* p) {
    int64_t i = skip_type_at(p, p->pos);
    if (i < 0) {
        return false;
    }
    if (((Token*)(p->toks).data)[i].kind != TkIdent) {
        return false;
    }
    i += 1;
    return (((Token*)(p->toks).data)[i].kind == TkLParen);
}

Decl* import_decl(Parser* p) {
    Token kw = p_expect(p, TkKwImport);
    Decl* d = new_decl(DcInclude, kw.line, kw.col);
    if (p_check(p, TkIdent)) {
        d->kind = DcImport;
        const char* path = p_advance(p).text;
        while (p_check(p, TkDot)) {
            p_advance(p);
            path = str_concat(str_concat(path, "."), p_expect(p, TkIdent).text);
        }
        d->path = path;
    } else 
    if (p_check(p, TkString)) {
        d->path = p_advance(p).text;
        d->is_system = false;
    } else 
    if (p_check(p, TkLt)) {
        p_advance(p);
        const char* path = "";
        while ((!p_check(p, TkGt)) && (!p_at_end(p))) {
            path = str_concat(path, p_advance(p).text);
        }
        p_expect(p, TkGt);
        d->path = path;
        d->is_system = true;
    } else {
        p_unexpected(p);
    }
    return d;
}

Decl* link_decl(Parser* p) {
    Token kw = p_expect(p, TkKwLink);
    Decl* d = new_decl(DcLink, kw.line, kw.col);
    d->path = p_expect(p, TkString).text;
    return d;
}

Decl* enum_decl(Parser* p) {
    Token kw = p_expect(p, TkKwEnum);
    Decl* ed = new_decl(DcEnum, kw.line, kw.col);
    ed->name = p_expect(p, TkIdent).text;
    p_expect(p, TkLBrace);
    skip_newlines(p);
    while ((!p_check(p, TkRBrace)) && (!p_at_end(p))) {
        ({ const char* _e = p_expect(p, TkIdent).text; arr_push(&(ed->members), &_e); });
        p_match(p, TkComma);
        skip_newlines(p);
    }
    p_expect(p, TkRBrace);
    return ed;
}

Decl* struct_decl(Parser* p) {
    Token kw = p_expect(p, TkKwStruct);
    Decl* sd = new_decl(DcStruct, kw.line, kw.col);
    sd->name = p_expect(p, TkIdent).text;
    p_expect(p, TkLBrace);
    skip_newlines(p);
    while ((!p_check(p, TkRBrace)) && (!p_at_end(p))) {
        TypeNode* fty = parse_type(p);
        const char* fnm = p_expect(p, TkIdent).text;
        ({ FieldDef _e = (FieldDef){fnm, fty}; arr_push(&(sd->fields), &_e); });
        p_match(p, TkSemicolon);
        skip_newlines(p);
    }
    p_expect(p, TkRBrace);
    return sd;
}

Decl* func_decl(Parser* p) {
    Token ft = p_peek(p);
    Decl* fd = new_decl(DcFunc, ft.line, ft.col);
    fd->ret = parse_type(p);
    fd->name = p_expect(p, TkIdent).text;
    p_expect(p, TkLParen);
    skip_newlines(p);
    if (!p_check(p, TkRParen)) {
        bool more = true;
        while (more) {
            TypeNode* pty = parse_type(p);
            const char* pnm = p_expect(p, TkIdent).text;
            ({ Param _e = (Param){pnm, pty}; arr_push(&(fd->params), &_e); });
            more = p_match(p, TkComma);
            skip_newlines(p);
        }
    }
    p_expect(p, TkRParen);
    fd->body = block(p);
    return fd;
}

Program parse_program(Parser* p) {
    Array decls = ({ Array _a = arr_make(sizeof(Decl*)); _a; });
    Array main = ({ Array _a = arr_make(sizeof(Stmt*)); _a; });
    skip_newlines(p);
    while ((!p_at_end(p)) && (!p->had_error)) {
        bool exported = false;
        if (p_check(p, TkKwExport)) {
            p_advance(p);
            exported = true;
            skip_newlines(p);
        }
        if (p_check(p, TkKwStruct)) {
            Decl* d = struct_decl(p);
            d->is_exported = exported;
            ({ Decl* _e = d; arr_push(&(decls), &_e); });
        } else 
        if (p_check(p, TkKwEnum)) {
            Decl* d = enum_decl(p);
            d->is_exported = exported;
            ({ Decl* _e = d; arr_push(&(decls), &_e); });
        } else 
        if (looks_like_func(p)) {
            Decl* d = func_decl(p);
            d->is_exported = exported;
            ({ Decl* _e = d; arr_push(&(decls), &_e); });
        } else 
        if (exported && p_check(p, TkKwImport)) {
            Decl* d = import_decl(p);
            if (d->kind != DcImport) {
                p_error(p, p_prev(p), "only a Strata module can be re-exported ('export import Name')");
            }
            d->is_exported = true;
            ({ Decl* _e = d; arr_push(&(decls), &_e); });
        } else 
        if (exported) {
            p_error(p, p_peek(p), "'export' must precede a declaration");
            p_advance(p);
        } else 
        if (p_check(p, TkKwImport)) {
            ({ Decl* _e = import_decl(p); arr_push(&(decls), &_e); });
        } else 
        if (p_check(p, TkKwLink)) {
            ({ Decl* _e = link_decl(p); arr_push(&(decls), &_e); });
        } else {
            int64_t before = p->pos;
            ({ Stmt* _e = statement(p); arr_push(&(main), &_e); });
            if (p->pos == before) {
                p_unexpected(p);
                p_advance(p);
            }
        }
        skip_newlines(p);
    }
    Array mods = ({ Array _a = arr_make(sizeof(Module)); _a; });
    return (Program){decls, main, mods};
}

Stmt* block(Parser* p) {
    Token lb = p_expect(p, TkLBrace);
    Stmt* b = new_stmt(StBlock, lb.line, lb.col);
    if (!nest_enter(p)) {
        return b;
    }
    skip_newlines(p);
    while ((!p_check(p, TkRBrace)) && (!p_at_end(p))) {
        int64_t before = p->pos;
        ({ Stmt* _e = statement(p); arr_push(&(b->stmts), &_e); });
        if (p->pos == before) {
            p_unexpected(p);
            p_advance(p);
        }
        skip_newlines(p);
    }
    p_expect(p, TkRBrace);
    p->depth -= 1;
    return b;
}

Stmt* var_decl_core(Parser* p) {
    Token st = p_peek(p);
    Stmt* s = new_stmt(StVar, st.line, st.col);
    if (p_match(p, TkKwConst)) {
        s->is_const = true;
        s->type = 0;
    } else 
    if (p_match(p, TkKwVar)) {
        s->type = 0;
    } else {
        s->type = parse_type(p);
    }
    s->name = p_expect(p, TkIdent).text;
    if (p_match(p, TkAssign)) {
        s->init = expression(p);
    }
    return s;
}

Stmt* expr_or_assign_core(Parser* p) {
    Expr* e = expression(p);
    TokKind t = p_peek(p).kind;
    if ((((((((((t == TkAssign) || (t == TkPlusEq)) || (t == TkMinusEq)) || (t == TkStarEq)) || (t == TkSlashEq)) || (t == TkPipeEq)) || (t == TkAmpEq)) || (t == TkCaretEq)) || (t == TkShlEq)) || (t == TkShrEq)) {
        Token op = p_advance(p);
        Stmt* s = new_stmt(StAssign, e->line, e->col);
        s->target = e;
        s->op = op.text;
        s->value = expression(p);
        return s;
    }
    Stmt* s = new_stmt(StExprStmt, e->line, e->col);
    s->expr = e;
    return s;
}

Stmt* return_stmt(Parser* p) {
    Token kw = p_advance(p);
    Stmt* s = new_stmt(StReturn, kw.line, kw.col);
    if ((((!p_check(p, TkNewline)) && (!p_check(p, TkSemicolon))) && (!p_check(p, TkRBrace))) && (!p_at_end(p))) {
        s->expr = expression(p);
    }
    return s;
}

Expr* header_expr(Parser* p) {
    bool saved = p->no_brace;
    p->no_brace = true;
    Expr* e = expression(p);
    p->no_brace = saved;
    return e;
}

Stmt* if_stmt(Parser* p) {
    Token kw = p_advance(p);
    Stmt* s = new_stmt(StIf, kw.line, kw.col);
    s->cond = header_expr(p);
    s->then_block = block(p);
    skip_newlines(p);
    if (p_match(p, TkKwElse)) {
        if (p_check(p, TkKwIf)) {
            s->else_branch = if_stmt(p);
        } else {
            s->else_branch = block(p);
        }
    }
    return s;
}

Stmt* while_stmt(Parser* p) {
    Token kw = p_advance(p);
    Stmt* s = new_stmt(StWhile, kw.line, kw.col);
    s->cond = header_expr(p);
    s->body = block(p);
    return s;
}

Stmt* for_stmt(Parser* p) {
    Token kw = p_advance(p);
    Stmt* s = new_stmt(StForIn, kw.line, kw.col);
    s->name = p_expect(p, TkIdent).text;
    p_expect(p, TkKwIn);
    s->iter = header_expr(p);
    s->body = block(p);
    return s;
}

Stmt* region_stmt(Parser* p) {
    Token kw = p_advance(p);
    Stmt* s = new_stmt(StRegion, kw.line, kw.col);
    if (p_check(p, TkIdent)) {
        s->name = p_advance(p).text;
    }
    s->body = block(p);
    return s;
}

Stmt* switch_stmt(Parser* p) {
    Token kw = p_advance(p);
    Stmt* s = new_stmt(StSwitch, kw.line, kw.col);
    s->subject = header_expr(p);
    p_expect(p, TkLBrace);
    skip_newlines(p);
    while ((!p_check(p, TkRBrace)) && (!p_at_end(p))) {
        Array vals = ({ Array _a = arr_make(sizeof(Expr*)); _a; });
        bool is_def = false;
        Token ct = p_peek(p);
        if (p_check(p, TkKwDefault)) {
            p_advance(p);
            is_def = true;
        } else 
        if (p_check(p, TkKwCase)) {
            p_advance(p);
            bool more = true;
            while (more) {
                ({ Expr* _e = expression(p); arr_push(&(vals), &_e); });
                more = p_match(p, TkComma);
            }
        } else {
            p_error(p, p_peek(p), str_concat("expected 'case' or 'default', got ", tok_desc(p_peek(p))));
            return s;
        }
        p_expect(p, TkColon);
        skip_newlines(p);
        Stmt* body = new_stmt(StBlock, ct.line, ct.col);
        while ((((!p_check(p, TkKwCase)) && (!p_check(p, TkKwDefault))) && (!p_check(p, TkRBrace))) && (!p_at_end(p))) {
            int64_t before = p->pos;
            ({ Stmt* _e = statement(p); arr_push(&(body->stmts), &_e); });
            if (p->pos == before) {
                p_unexpected(p);
                p_advance(p);
            }
            skip_newlines(p);
        }
        ({ SwitchCase _e = (SwitchCase){vals, body, is_def, ct.line, ct.col}; arr_push(&(s->cases), &_e); });
    }
    p_expect(p, TkRBrace);
    return s;
}

Stmt* statement(Parser* p) {
    switch (p_peek(p).kind) {
        case TkKwReturn:
        {
            return return_stmt(p);
            break;
        }
        case TkKwIf:
        {
            return if_stmt(p);
            break;
        }
        case TkKwWhile:
        {
            return while_stmt(p);
            break;
        }
        case TkKwFor:
        {
            return for_stmt(p);
            break;
        }
        case TkKwRegion:
        {
            return region_stmt(p);
            break;
        }
        case TkKwSwitch:
        {
            return switch_stmt(p);
            break;
        }
        case TkKwBreak:
        case TkKwContinue:
        {
            {
                Token kw = p_advance(p);
                if (kw.kind == TkKwBreak) {
                    return new_stmt(StBreak, kw.line, kw.col);
                }
                return new_stmt(StContinue, kw.line, kw.col);
            }
            break;
        }
        case TkLBrace:
        {
            return block(p);
            break;
        }
        case TkKwVar:
        case TkKwConst:
        {
            return var_decl_core(p);
            break;
        }
        default: {
            if (looks_like_typed_decl(p)) {
                return var_decl_core(p);
            }
            return expr_or_assign_core(p);
            break;
        }
    }
    return 0;
}

Expr* make_binary(const char* op, Expr* lhs, Expr* rhs) {
    Expr* e = new_expr(ExBinary, lhs->line, lhs->col);
    e->text = op;
    e->a = lhs;
    e->b = rhs;
    return e;
}

int64_t max_nesting(void) {
    return 1000;
}

bool nest_enter(Parser* p) {
    p->depth += 1;
    if (p->depth > max_nesting()) {
        p_error(p, p_peek(p), str_concat(str_concat("code is nested too deeply (more than ", str_from_int(max_nesting())), " levels)"));
        p->depth -= 1;
        return false;
    }
    return true;
}

Expr* expression(Parser* p) {
    if (!nest_enter(p)) {
        Token t = p_peek(p);
        p_advance(p);
        return new_expr(ExName, t.line, t.col);
    }
    Expr* e = range_expr(p);
    p->depth -= 1;
    return e;
}

Expr* range_expr(Parser* p) {
    Expr* e = or_expr(p);
    if (p_check(p, TkDotDot)) {
        p_advance(p);
        e = make_binary("..", e, or_expr(p));
    }
    return e;
}

Expr* or_expr(Parser* p) {
    Expr* e = and_expr(p);
    while (p_check(p, TkPipePipe)) {
        p_advance(p);
        e = make_binary("||", e, and_expr(p));
    }
    return e;
}

Expr* and_expr(Parser* p) {
    Expr* e = bit_or(p);
    while (p_check(p, TkAmpAmp)) {
        p_advance(p);
        e = make_binary("&&", e, bit_or(p));
    }
    return e;
}

Expr* bit_or(Parser* p) {
    Expr* e = bit_xor(p);
    while (p_check(p, TkPipe)) {
        p_advance(p);
        e = make_binary("|", e, bit_xor(p));
    }
    return e;
}

Expr* bit_xor(Parser* p) {
    Expr* e = bit_and(p);
    while (p_check(p, TkCaret)) {
        p_advance(p);
        e = make_binary("^", e, bit_and(p));
    }
    return e;
}

Expr* bit_and(Parser* p) {
    Expr* e = equality(p);
    while (p_check(p, TkAmp)) {
        p_advance(p);
        e = make_binary("&", e, equality(p));
    }
    return e;
}

Expr* equality(Parser* p) {
    Expr* e = comparison(p);
    while (p_check(p, TkEqEq) || p_check(p, TkBangEq)) {
        const char* op = p_advance(p).text;
        e = make_binary(op, e, comparison(p));
    }
    return e;
}

Expr* comparison(Parser* p) {
    Expr* e = shift(p);
    while (((p_check(p, TkLt) || p_check(p, TkLtEq)) || p_check(p, TkGt)) || p_check(p, TkGtEq)) {
        const char* op = p_advance(p).text;
        e = make_binary(op, e, shift(p));
    }
    return e;
}

Expr* shift(Parser* p) {
    Expr* e = term(p);
    while (p_check(p, TkShl) || p_check(p, TkShr)) {
        const char* op = p_advance(p).text;
        e = make_binary(op, e, term(p));
    }
    return e;
}

Expr* term(Parser* p) {
    Expr* e = factor(p);
    while (p_check(p, TkPlus) || p_check(p, TkMinus)) {
        const char* op = p_advance(p).text;
        e = make_binary(op, e, factor(p));
    }
    return e;
}

Expr* factor(Parser* p) {
    Expr* e = unary(p);
    while ((p_check(p, TkStar) || p_check(p, TkSlash)) || p_check(p, TkPercent)) {
        const char* op = p_advance(p).text;
        e = make_binary(op, e, unary(p));
    }
    return e;
}

Expr* unary(Parser* p) {
    if ((((p_check(p, TkBang) || p_check(p, TkMinus)) || p_check(p, TkStar)) || p_check(p, TkAmp)) || p_check(p, TkTilde)) {
        Token op = p_advance(p);
        Expr* u = new_expr(ExUnary, op.line, op.col);
        u->text = op.text;
        if (!nest_enter(p)) {
            return u;
        }
        u->a = unary(p);
        p->depth -= 1;
        return u;
    }
    return postfix(p);
}

Expr* postfix(Parser* p) {
    Expr* e = primary(p);
    while (true) {
        if (p_match(p, TkDot)) {
            Expr* f = new_expr(ExField, e->line, e->col);
            f->a = e;
            f->field = p_expect(p, TkIdent).text;
            e = f;
        } else 
        if (p_match(p, TkLParen)) {
            Expr* c = new_expr(ExCall, e->line, e->col);
            c->a = e;
            bool saved = p->no_brace;
            p->no_brace = false;
            skip_newlines(p);
            if (!p_check(p, TkRParen)) {
                bool more = true;
                while (more) {
                    ({ Expr* _e = expression(p); arr_push(&(c->items), &_e); });
                    skip_newlines(p);
                    more = p_match(p, TkComma);
                    skip_newlines(p);
                }
            }
            p->no_brace = saved;
            p_expect(p, TkRParen);
            e = c;
        } else 
        if (p_match(p, TkLBracket)) {
            Expr* ix = new_expr(ExIndex, e->line, e->col);
            ix->a = e;
            bool saved = p->no_brace;
            p->no_brace = false;
            ix->b = expression(p);
            p->no_brace = saved;
            p_expect(p, TkRBracket);
            e = ix;
        } else {
            return e;
        }
    }
    return e;
}

Expr* primary(Parser* p) {
    Token t = p_peek(p);
    if (t.kind == TkKwCast) {
        p_advance(p);
        Expr* cx = new_expr(ExCast, t.line, t.col);
        p_expect(p, TkLt);
        cx->type = parse_type(p);
        p_expect(p, TkGt);
        p_expect(p, TkLParen);
        bool saved = p->no_brace;
        p->no_brace = false;
        cx->a = expression(p);
        p->no_brace = saved;
        p_expect(p, TkRParen);
        return cx;
    }
    if (t.kind == TkKwSizeof) {
        p_advance(p);
        Expr* sz = new_expr(ExSizeof, t.line, t.col);
        p_expect(p, TkLParen);
        sz->type = parse_type(p);
        p_expect(p, TkRParen);
        return sz;
    }
    switch (t.kind) {
        case TkInt:
        {
            {
                p_advance(p);
                Expr* e = new_expr(ExIntLit, t.line, t.col);
                e->text = t.text;
                return e;
            }
            break;
        }
        case TkFloat:
        {
            {
                p_advance(p);
                Expr* e = new_expr(ExFloatLit, t.line, t.col);
                e->text = t.text;
                return e;
            }
            break;
        }
        case TkString:
        {
            {
                p_advance(p);
                Expr* e = new_expr(ExStringLit, t.line, t.col);
                e->text = t.text;
                return e;
            }
            break;
        }
        case TkChar:
        {
            {
                p_advance(p);
                Expr* e = new_expr(ExCharLit, t.line, t.col);
                e->text = t.text;
                return e;
            }
            break;
        }
        case TkKwTrue:
        {
            {
                p_advance(p);
                Expr* e = new_expr(ExBoolLit, t.line, t.col);
                e->bval = true;
                return e;
            }
            break;
        }
        case TkKwFalse:
        {
            {
                p_advance(p);
                Expr* e = new_expr(ExBoolLit, t.line, t.col);
                e->bval = false;
                return e;
            }
            break;
        }
        case TkLParen:
        {
            {
                p_advance(p);
                bool saved = p->no_brace;
                p->no_brace = false;
                Expr* e = expression(p);
                p->no_brace = saved;
                p_expect(p, TkRParen);
                return e;
            }
            break;
        }
        case TkLBracket:
        {
            {
                p_advance(p);
                Expr* a = new_expr(ExArrayLit, t.line, t.col);
                bool saved = p->no_brace;
                p->no_brace = false;
                skip_newlines(p);
                if (!p_check(p, TkRBracket)) {
                    bool more = true;
                    while (more) {
                        ({ Expr* _e = expression(p); arr_push(&(a->items), &_e); });
                        skip_newlines(p);
                        more = p_match(p, TkComma);
                        skip_newlines(p);
                    }
                }
                p->no_brace = saved;
                p_expect(p, TkRBracket);
                return a;
            }
            break;
        }
        case TkIdent:
        {
            {
                if ((!p->no_brace) && (p_peek_at(p, 1).kind == TkLBrace)) {
                    p_advance(p);
                    p_advance(p);
                    Expr* s = new_expr(ExStructLit, t.line, t.col);
                    s->type_name = t.text;
                    bool saved = p->no_brace;
                    p->no_brace = false;
                    skip_newlines(p);
                    if (!p_check(p, TkRBrace)) {
                        bool more = true;
                        while (more) {
                            ({ Expr* _e = expression(p); arr_push(&(s->items), &_e); });
                            skip_newlines(p);
                            more = p_match(p, TkComma);
                            skip_newlines(p);
                        }
                    }
                    p->no_brace = saved;
                    p_expect(p, TkRBrace);
                    return s;
                }
                p_advance(p);
                Expr* e = new_expr(ExName, t.line, t.col);
                e->text = t.text;
                return e;
            }
            break;
        }
        default: {
            p_error(p, t, str_concat("expected an expression, got ", tok_desc(t)));
            p_advance(p);
            return new_expr(ExName, t.line, t.col);
            break;
        }
    }
    return new_expr(ExName, t.line, t.col);
}

const char* stem_of(const char* p) {
    int64_t dot = (0 - 1);
    int64_t slash = (0 - 1);
    for (int64_t i = 0; i < str_len(p); i++) {
        if (p[i] == '.') {
            dot = i;
        }
        if ((p[i] == '/') || (p[i] == '\\')) {
            slash = i;
        }
    }
    if ((dot >= 0) && ((slash < 0) || (dot > slash))) {
        return str_sub(p, 0, dot);
    }
    return p;
}

const char* basename_of(const char* p) {
    int64_t slash = (0 - 1);
    for (int64_t i = 0; i < str_len(p); i++) {
        if ((p[i] == '/') || (p[i] == '\\')) {
            slash = i;
        }
    }
    return str_sub(p, (slash + 1), (str_len(p) - (slash + 1)));
}

const char* dirname_of(const char* p) {
    int64_t slash = (0 - 1);
    for (int64_t i = 0; i < str_len(p); i++) {
        if ((p[i] == '/') || (p[i] == '\\')) {
            slash = i;
        }
    }
    if (slash < 0) {
        return ".";
    }
    return str_sub(p, 0, slash);
}

const char* module_rel_path(const char* name) {
    const char* rel = "";
    for (int64_t i = 0; i < str_len(name); i++) {
        if (name[i] == '.') {
            rel = str_concat(rel, "/");
        } else {
            rel = str_concat(rel, str_sub(name, i, 1));
        }
    }
    return str_concat(rel, ".strata");
}

void ld_error(Loader* ld, const char* file, int64_t line, int64_t col, const char* msg) {
    ld->had_error = true;
    strata_report(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(file, ":"), str_from_int(line)), ":"), str_from_int(col)), ": error: "), msg));
}

int64_t ld_find(Loader* ld, const char* path) {
    for (int64_t i = 0; i < ld->prog.modules.len; i++) {
        if (str_eq(((Module*)(ld->prog.modules).data)[i].path, path)) {
            return i;
        }
    }
    return (0 - 1);
}

int64_t ld_module(Loader* ld, const char* path, const char* file, const char* name, bool is_root) {
    int64_t existing = ld_find(ld, path);
    if (existing >= 0) {
        return existing;
    }
    int64_t idx = ld->prog.modules.len;
    ({ Module _e = new_module(name, path, file); arr_push(&(ld->prog.modules), &_e); });
    const char* src = "";
    if (is_root && ld->has_text) {
        src = str_sub(ld->root_text, 0, str_len(ld->root_text));
    } else {
        src = strata_read_file(path);
    }
    Parser p = new_parser(lex(src));
    Program part = parse_program((&p));
    strata_array_free((&p.toks));
    if (p.had_error) {
        strata_report(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(file, ":"), str_from_int(p.err_line)), ":"), str_from_int(p.err_col)), ": parse error: "), p.err_msg));
        ld->had_error = true;
        return idx;
    }
    if (is_root) {
        ld->prog.main = part.main;
    } else 
    if (part.main.len > 0) {
        Stmt* s = ((Stmt**)(part.main).data)[0];
        ld_error(ld, file, s->line, s->col, "a module can only contain declarations; top-level code is only allowed in the main file");
    }
    for (int64_t i = 0; i < part.decls.len; i++) {
        Decl* d = ((Decl**)(part.decls).data)[i];
        d->module = idx;
        if (d->kind == DcImport) {
            const char* rel = module_rel_path(d->path);
            const char* mpath = str_concat(str_concat(ld->root, "/"), rel);
            if (str_len(strata_read_file(mpath)) == 0) {
                ld_error(ld, file, d->line, d->col, str_concat(str_concat(str_concat(str_concat("cannot find module '", d->path), "' (looked for "), rel), " in the project folder)"));
            } else {
                int64_t m = ld_module(ld, mpath, rel, d->path, false);
                ({ int64_t _e = m; arr_push(&(((Module*)(ld->prog.modules).data)[idx].imports), &_e); });
                if (d->is_exported) {
                    ({ int64_t _e = m; arr_push(&(((Module*)(ld->prog.modules).data)[idx].reexports), &_e); });
                }
            }
        } else {
            ({ Decl* _e = d; arr_push(&(ld->prog.decls), &_e); });
        }
    }
    return idx;
}

LoadResult load_program(const char* path) {
    return load_program_impl(path, false, "");
}

LoadResult load_program_text(const char* path, const char* text) {
    return load_program_impl(path, true, text);
}

LoadResult load_program_impl(const char* path, bool has_text, const char* text) {
    Array decls = ({ Array _a = arr_make(sizeof(Decl*)); _a; });
    Array main = ({ Array _a = arr_make(sizeof(Stmt*)); _a; });
    Array mods = ({ Array _a = arr_make(sizeof(Module)); _a; });
    Loader ld = (Loader){(Program){decls, main, mods}, false, dirname_of(path), has_text, text};
    ld_module((&ld), path, basename_of(path), stem_of(basename_of(path)), true);
    return (LoadResult){ld.prog, (!ld.had_error)};
}

