void ck_name_conflicts(Checker* c) {
    for (int64_t j = 0; j < c->names.len; j++) {
        NameEntry b = ((NameEntry*)(c->names).data)[j];
        c->cur = b.module;
        Array dups = ({ Array _a = arr_make(sizeof(int64_t)); _a; });
        int64_t conflict = (0 - 1);
        int64_t k = idx_first((&c->name_idx), b.name);
        while (k >= 0) {
            NameEntry o = ((NameEntry*)(c->names).data)[k];
            if ((str_eq(o.name, b.name) && (o.module != b.module)) && o.exported) {
                if ((k < j) && b.exported) {
                    ({ int64_t _e = k; arr_push(&(dups), &_e); });
                }
                if ((!b.exported) && ck_sees(c, o.module, true)) {
                    conflict = k;
                }
            }
            k = idx_next((&c->name_idx), k);
        }
        int64_t d = (dups.len - 1);
        while (d >= 0) {
            ck_error(c, b.line, b.col, str_concat(str_concat(str_concat(str_concat("'", b.name), "' is also exported by "), ((Module*)(c->mods).data)[((NameEntry*)(c->names).data)[((int64_t*)(dups).data)[d]].module].file), " (exported names must be unique across the program)"));
            d -= 1;
        }
        if (conflict >= 0) {
            ck_error(c, b.line, b.col, str_concat(str_concat(str_concat(str_concat(str_concat(str_concat("'", b.name), "' conflicts with the '"), b.name), "' exported by "), ((Module*)(c->mods).data)[((NameEntry*)(c->names).data)[conflict].module].file), ", which this file imports"));
        }
    }
}

bool ck_check(Checker* c, Program prog) {
    c->mods = prog.modules;
    if (c->mods.len == 0) {
        ({ Module _e = new_module(c->file, c->file, c->file); arr_push(&(c->mods), &_e); });
    }
    ck_visibility(c);
    for (int64_t i = 0; i < prog.decls.len; i++) {
        if (((Decl**)(prog.decls).data)[i]->kind == DcInclude) {
            c->has_foreign = true;
        }
    }
    int64_t n_all = 0;
    for (int64_t i = 0; i < prog.decls.len; i++) {
        n_all = ((n_all + 1) + ((Decl**)(prog.decls).data)[i]->members.len);
    }
    c->struct_idx = new_idx(n_all);
    c->func_idx = new_idx(n_all);
    c->enum_idx = new_idx(n_all);
    c->member_idx = new_idx(n_all);
    c->name_idx = new_idx(n_all);
    c->node_idx = new_idx(n_all);
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        c->cur = d->module;
        if (d->kind == DcEnum) {
            if (ck_own_enum(c, d->name, d->module) >= 0) {
                ck_error(c, d->line, d->col, str_concat(str_concat("enum '", d->name), "' is already defined"));
            }
            idx_add((&c->enum_idx), d->name, c->enums.len);
            ({ EnumInfo _e = (EnumInfo){d->name, d->module, d->is_exported, d->name}; arr_push(&(c->enums), &_e); });
            ck_note_name(c, d->name, d->module, d->is_exported, d->line, d->col);
            for (int64_t m = 0; m < d->members.len; m++) {
                const char* mem = ((const char**)(d->members).data)[m];
                if (ck_own_member(c, mem, d->module) >= 0) {
                    ck_error(c, d->line, d->col, str_concat(str_concat("enum member '", mem), "' is already defined"));
                }
                idx_add((&c->member_idx), mem, c->enum_members.len);
                ({ EnumMember _e = (EnumMember){mem, d->name, d->module, d->is_exported, mem}; arr_push(&(c->enum_members), &_e); });
                ck_note_name(c, mem, d->module, d->is_exported, d->line, d->col);
            }
        } else 
        if (d->kind == DcStruct) {
            if (ck_own_struct(c, d->name, d->module) >= 0) {
                ck_error(c, d->line, d->col, str_concat(str_concat("struct '", d->name), "' is already defined"));
            }
            Array ff = ({ Array _a = arr_make(sizeof(FieldInfo)); _a; });
            idx_add((&c->struct_idx), d->name, c->structs.len);
            ({ StructInfo _e = (StructInfo){d->name, ff, d->module, d->is_exported, d->name}; arr_push(&(c->structs), &_e); });
            ck_note_name(c, d->name, d->module, d->is_exported, d->line, d->col);
        } else 
        if (d->kind == DcFunc) {
            if (ck_own_func(c, d->name, d->module) >= 0) {
                ck_error(c, d->line, d->col, str_concat(str_concat("function '", d->name), "' is already defined"));
            }
            Array ps = ({ Array _a = arr_make(sizeof(Type*)); _a; });
            idx_add((&c->func_idx), d->name, c->funcs.len);
            ({ FuncInfo _e = (FuncInfo){d->name, ps, c->t_void, d->module, d->is_exported, d->name}; arr_push(&(c->funcs), &_e); });
            ck_note_name(c, d->name, d->module, d->is_exported, d->line, d->col);
        }
    }
    for (int64_t i = 0; i < c->enums.len; i++) {
        ((EnumInfo*)(c->enums).data)[i].cname = ck_cname(c, ((EnumInfo*)(c->enums).data)[i].name, ((EnumInfo*)(c->enums).data)[i].module, ((EnumInfo*)(c->enums).data)[i].exported);
    }
    for (int64_t i = 0; i < c->enum_members.len; i++) {
        EnumMember m = ((EnumMember*)(c->enum_members).data)[i];
        ((EnumMember*)(c->enum_members).data)[i].cname = ck_cname(c, m.member, m.module, m.exported);
        ((EnumMember*)(c->enum_members).data)[i].enum_name = ((EnumInfo*)(c->enums).data)[ck_own_enum(c, m.enum_name, m.module)].cname;
    }
    for (int64_t i = 0; i < c->structs.len; i++) {
        ((StructInfo*)(c->structs).data)[i].cname = ck_cname(c, ((StructInfo*)(c->structs).data)[i].name, ((StructInfo*)(c->structs).data)[i].module, ((StructInfo*)(c->structs).data)[i].exported);
    }
    c->cname_idx = new_idx(c->structs.len);
    for (int64_t i = 0; i < c->structs.len; i++) {
        idx_add((&c->cname_idx), ((StructInfo*)(c->structs).data)[i].cname, i);
    }
    for (int64_t i = 0; i < c->funcs.len; i++) {
        ((FuncInfo*)(c->funcs).data)[i].cname = ck_cname(c, ((FuncInfo*)(c->funcs).data)[i].name, ((FuncInfo*)(c->funcs).data)[i].module, ((FuncInfo*)(c->funcs).data)[i].exported);
    }
    ck_name_conflicts(c);
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcStruct) {
            c->cur = d->module;
            int64_t si = ck_own_struct(c, d->name, d->module);
            for (int64_t fld = 0; fld < d->fields.len; fld++) {
                ({ FieldInfo _e = (FieldInfo){((FieldDef*)(d->fields).data)[fld].name, ck_type(c, ((FieldDef*)(d->fields).data)[fld].type)}; arr_push(&(((StructInfo*)(c->structs).data)[si].fields), &_e); });
            }
        }
    }
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcFunc) {
            c->cur = d->module;
            int64_t fi = ck_own_func(c, d->name, d->module);
            for (int64_t pi = 0; pi < d->params.len; pi++) {
                ({ Type* _e = ck_type(c, ((Param*)(d->params).data)[pi].type); arr_push(&(((FuncInfo*)(c->funcs).data)[fi].params), &_e); });
            }
            ((FuncInfo*)(c->funcs).data)[fi].ret = ck_type(c, d->ret);
        }
    }
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcFunc) {
            c->cur = d->module;
            ck_func(c, d, ck_own_func(c, d->name, d->module));
        }
    }
    c->cur = 0;
    c->cur_ret = c->t_void;
    ck_push(c);
    for (int64_t i = 0; i < prog.main.len; i++) {
        ck_stmt(c, ((Stmt**)(prog.main).data)[i]);
    }
    ck_pop(c);
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcFunc) {
            d->name = ((FuncInfo*)(c->funcs).data)[ck_own_func(c, d->name, d->module)].cname;
        }
        if (d->kind == DcStruct) {
            d->name = ((StructInfo*)(c->structs).data)[ck_own_struct(c, d->name, d->module)].cname;
        }
        if (d->kind == DcEnum) {
            for (int64_t m = 0; m < d->members.len; m++) {
                ((const char**)(d->members).data)[m] = ((EnumMember*)(c->enum_members).data)[ck_own_member(c, ((const char**)(d->members).data)[m], d->module)].cname;
            }
            d->name = ((EnumInfo*)(c->enums).data)[ck_own_enum(c, d->name, d->module)].cname;
        }
    }
    return (!c->had_error);
}

