BinParts gen_binary(Codegen* cg, Expr* e, const char* b) {
    if (((cg_is_mat_rt(e->a->rtype) || cg_is_quat_rt(e->a->rtype)) || cg_is_mat_rt(e->b->rtype)) || cg_is_quat_rt(e->b->rtype)) {
        if (cg_is_mat_rt(e->a->rtype) && cg_is_mat_rt(e->b->rtype)) {
            return (BinParts){"mat4_mul(", str_concat(str_concat(", ", b), ")")};
        }
        if (cg_is_mat_rt(e->a->rtype) && cg_is_vec_rt(e->b->rtype)) {
            return (BinParts){"mat4_mul_vec4(", str_concat(str_concat(", ", b), ")")};
        }
        if (cg_is_quat_rt(e->a->rtype) && cg_is_quat_rt(e->b->rtype)) {
            return (BinParts){"quat_mul(", str_concat(str_concat(", ", b), ")")};
        }
        cg->had_error = true;
        return (BinParts){"", ""};
    }
    bool av = cg_is_vec_rt(e->a->rtype);
    bool bv = cg_is_vec_rt(e->b->rtype);
    if (av || bv) {
        const char* vn = cg_vec_name_rt(e->a->rtype);
        if (str_len(vn) == 0) {
            vn = cg_vec_name_rt(e->b->rtype);
        }
        if (str_eq(e->text, "+")) {
            return (BinParts){str_concat(vn, "_add("), str_concat(str_concat(", ", b), ")")};
        }
        if (str_eq(e->text, "-")) {
            return (BinParts){str_concat(vn, "_sub("), str_concat(str_concat(", ", b), ")")};
        }
        if (str_eq(e->text, "*")) {
            if (av && bv) {
                return (BinParts){str_concat(vn, "_mul("), str_concat(str_concat(", ", b), ")")};
            }
            if (av) {
                return (BinParts){str_concat(vn, "_scale("), str_concat(str_concat(", ", b), ")")};
            }
            return (BinParts){str_concat(str_concat(str_concat(vn, "_scale("), b), ", "), ")"};
        }
        cg->had_error = true;
        return (BinParts){"", ""};
    }
    if (cg_is_str_rt(e->a->rtype) || cg_is_str_rt(e->b->rtype)) {
        if (str_eq(e->text, "+")) {
            return (BinParts){"str_concat(", str_concat(str_concat(", ", b), ")")};
        }
        if (str_eq(e->text, "==")) {
            return (BinParts){"str_eq(", str_concat(str_concat(", ", b), ")")};
        }
        if (str_eq(e->text, "!=")) {
            return (BinParts){"(!str_eq(", str_concat(str_concat(", ", b), "))")};
        }
        cg->had_error = true;
        return (BinParts){"", ""};
    }
    return (BinParts){"(", str_concat(str_concat(str_concat(str_concat(" ", e->text), " "), b), ")")};
}

const char* gen_expr(Codegen* cg, Expr* e) {
    if (e == 0) {
        return "0";
    }
    switch (e->kind) {
        case ExIntLit:
        {
            return cg_strip_us(e->text);
            break;
        }
        case ExFloatLit:
        {
            return cg_strip_us(e->text);
            break;
        }
        case ExStringLit:
        {
            return str_concat(str_concat("\"", cg_escape(e->text)), "\"");
            break;
        }
        case ExCharLit:
        {
            return str_concat(str_concat("'", cg_escape(e->text)), "'");
            break;
        }
        case ExBoolLit:
        {
            if (e->bval) {
                return "true";
            }
            return "false";
            break;
        }
        case ExName:
        {
            if (str_eq(e->text, "PI")) {
                return "SP_PI";
            }
            if (str_eq(e->text, "null")) {
                return "0";
            }
            return e->text;
            break;
        }
        case ExUnary:
        {
            return str_concat(str_concat(str_concat("(", e->text), gen_expr(cg, e->a)), ")");
            break;
        }
        case ExBinary:
        {
            {
                if (str_eq(e->text, "..")) {
                    cg->had_error = true;
                    return "0";
                }
                Array spine = ({ Array _a = arr_make(sizeof(Expr*)); _a; });
                Expr* x = e;
                while ((x->kind == ExBinary) && (!str_eq(x->text, ".."))) {
                    ({ Expr* _e = x; arr_push(&(spine), &_e); });
                    x = x->a;
                }
                const char* inner = gen_expr(cg, x);
                Array pre = ({ Array _a = arr_make(sizeof(const char*)); _a; });
                Array post = ({ Array _a = arr_make(sizeof(const char*)); _a; });
                int64_t k = (spine.len - 1);
                while (k >= 0) {
                    BinParts bp = gen_binary(cg, ((Expr**)(spine).data)[k], gen_expr(cg, ((Expr**)(spine).data)[k]->b));
                    ({ const char* _e = bp.pre; arr_push(&(pre), &_e); });
                    ({ const char* _e = bp.post; arr_push(&(post), &_e); });
                    k -= 1;
                }
                Array out = ({ Array _a = arr_make(sizeof(const char*)); _a; });
                int64_t m = (pre.len - 1);
                while (m >= 0) {
                    ({ const char* _e = ((const char**)(pre).data)[m]; arr_push(&(out), &_e); });
                    m -= 1;
                }
                ({ const char* _e = inner; arr_push(&(out), &_e); });
                for (int64_t i = 0; i < post.len; i++) {
                    ({ const char* _e = ((const char**)(post).data)[i]; arr_push(&(out), &_e); });
                }
                return strata_join((&out));
            }
            break;
        }
        case ExCall:
        {
            return gen_call(cg, e);
            break;
        }
        case ExField:
        {
            {
                if (cg_is_str_rt(e->a->rtype) && str_eq(e->field, "len")) {
                    return str_concat(str_concat("str_len(", gen_expr(cg, e->a)), ")");
                }
                if (cg_is_vec_rt(e->a->rtype) && (str_len(e->field) > 1)) {
                    const char* base = gen_expr(cg, e->a);
                    const char* vt = "vec2";
                    if (str_len(e->field) == 3) {
                        vt = "vec3";
                    }
                    if (str_len(e->field) == 4) {
                        vt = "vec4";
                    }
                    const char* s = str_concat(str_concat("(", vt), "){");
                    for (int64_t i = 0; i < str_len(e->field); i++) {
                        if (i > 0) {
                            s = str_concat(s, ", ");
                        }
                        s = str_concat(str_concat(str_concat(str_concat(s, "("), base), ")."), str_sub(e->field, i, 1));
                    }
                    return str_concat(s, "}");
                }
                const char* op = ".";
                if ((e->a->rtype != 0) && (e->a->rtype->kind == TyPointer)) {
                    op = "->";
                }
                return str_concat(str_concat(gen_expr(cg, e->a), op), e->field);
            }
            break;
        }
        case ExIndex:
        {
            {
                if (cg_is_dynarr_rt(e->a->rtype)) {
                    const char* elemc = cg_dynarr_elem(e->a->rtype);
                    return str_concat(str_concat(str_concat(str_concat(str_concat(str_concat("((", elemc), "*)("), gen_expr(cg, e->a)), ").data)["), gen_expr(cg, e->b)), "]");
                }
                return str_concat(str_concat(str_concat(gen_expr(cg, e->a), "["), gen_expr(cg, e->b)), "]");
            }
            break;
        }
        case ExArrayLit:
        {
            {
                const char* elemc = "int64_t";
                if (((e->rtype != 0) && (e->rtype->kind == TyDynArray)) && (e->rtype->elem != 0)) {
                    elemc = ty_to_c(e->rtype->elem);
                }
                const char* s = str_concat(str_concat("({ Array _a = arr_make(sizeof(", elemc), "));");
                Array a = ({ Array _a = arr_make(sizeof(const char*)); _a; });
                ({ const char* _e = s; arr_push(&(a), &_e); });
                for (int64_t i = 0; i < e->items.len; i++) {
                    ({ const char* _e = str_concat(str_concat(str_concat(str_concat(" { ", elemc), " _e = "), gen_expr(cg, ((Expr**)(e->items).data)[i])), "; arr_push(&_a, &_e); }"); arr_push(&(a), &_e); });
                }
                s = strata_join((&a));
                return str_concat(s, " _a; })");
            }
            break;
        }
        case ExStructLit:
        {
            {
                const char* s = str_concat(str_concat("(", cname(e->type_name)), "){");
                Array a = ({ Array _a = arr_make(sizeof(const char*)); _a; });
                for (int64_t i = 0; i < e->items.len; i++) {
                    ({ const char* _e = gen_expr(cg, ((Expr**)(e->items).data)[i]); arr_push(&(a), &_e); });
                }
                return str_concat(str_concat(s, join_with(a, ", ")), "}");
            }
            break;
        }
        case ExCast:
        {
            return str_concat(str_concat(str_concat(str_concat("((", ty_to_c(e->type)), ")("), gen_expr(cg, e->a)), "))");
            break;
        }
        case ExSizeof:
        {
            return str_concat(str_concat("((int64_t)sizeof(", ty_to_c(e->type)), "))");
            break;
        }
        default: {
            cg->had_error = true;
            return "0";
            break;
        }
    }
    return "0";
}

void gen_braced(Codegen* cg, int64_t ind, Stmt* blk) {
    cg_out(cg, "{\n");
    if ((blk != 0) && (blk->kind == StBlock)) {
        for (int64_t i = 0; i < blk->stmts.len; i++) {
            gen_stmt(cg, (ind + 1), ((Stmt**)(blk->stmts).data)[i]);
        }
    }
    cg_out(cg, str_concat(cg_indent(ind), "}"));
}

void gen_stmt(Codegen* cg, int64_t ind, Stmt* s) {
    if (s == 0) {
        return;
    }
    switch (s->kind) {
        case StBlock:
        {
            cg_out(cg, cg_indent(ind));
            gen_braced(cg, ind, s);
            cg_out(cg, "\n");
            break;
        }
        case StVar:
        {
            {
                const char* ct = "__auto_type";
                if (s->type != 0) {
                    ct = ty_to_c(s->type);
                }
                const char* head = "";
                if (s->is_const) {
                    head = "const ";
                }
                if (s->init != 0) {
                    cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent(ind), head), ct), " "), s->name), " = "), gen_expr(cg, s->init)), ";\n"));
                } else 
                if ((s->type != 0) && (s->type->kind == TyDynArray)) {
                    cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent(ind), "Array "), s->name), " = arr_make(sizeof("), ty_to_c(s->type->elem)), "));\n"));
                } else {
                    cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent(ind), head), ct), " "), s->name), ";\n"));
                }
            }
            break;
        }
        case StReturn:
        {
            if (cg->regions.len == 0) {
                if (s->expr != 0) {
                    cg_out(cg, str_concat(str_concat(str_concat(cg_indent(ind), "return "), gen_expr(cg, s->expr)), ";\n"));
                } else {
                    cg_out(cg, str_concat(cg_indent(ind), "return;\n"));
                }
            } else 
            if (s->expr != 0) {
                cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent(ind), "{ "), cg->ret_c), " _ret = "), gen_expr(cg, s->expr)), ";\n"));
                cg_out(cg, region_frees(cg, 0, (ind + 1)));
                cg_out(cg, str_concat(cg_indent((ind + 1)), "return _ret; }\n"));
            } else {
                cg_out(cg, str_concat(str_concat(str_concat(str_concat(cg_indent(ind), "{\n"), region_frees(cg, 0, (ind + 1))), cg_indent((ind + 1))), "return; }\n"));
            }
            break;
        }
        case StBreak:
        case StContinue:
        {
            {
                int64_t top = (cg->loop_labels.len - 1);
                cg_out(cg, region_frees(cg, ((int64_t*)(cg->loop_regions).data)[top], ind));
                if (s->kind == StContinue) {
                    cg_out(cg, str_concat(cg_indent(ind), "continue;\n"));
                } else 
                if (cg->switch_depth > ((int64_t*)(cg->loop_switches).data)[top]) {
                    ((int64_t*)(cg->loop_label_used).data)[top] = 1;
                    cg_out(cg, str_concat(str_concat(str_concat(cg_indent(ind), "goto strata_break_"), str_from_int(((int64_t*)(cg->loop_labels).data)[top])), ";\n"));
                } else {
                    cg_out(cg, str_concat(cg_indent(ind), "break;\n"));
                }
            }
            break;
        }
        case StExprStmt:
        {
            cg_out(cg, str_concat(str_concat(cg_indent(ind), gen_expr(cg, s->expr)), ";\n"));
            break;
        }
        case StAssign:
        {
            {
                if ((!str_eq(s->op, "=")) && cg_is_vec_rt(s->target->rtype)) {
                    const char* vn = cg_vec_name_rt(s->target->rtype);
                    const char* tgt = gen_expr(cg, s->target);
                    const char* val = gen_expr(cg, s->value);
                    const char* rhs = "0";
                    if (str_eq(s->op, "+=")) {
                        rhs = str_concat(str_concat(str_concat(str_concat(str_concat(vn, "_add("), tgt), ", "), val), ")");
                    } else 
                    if (str_eq(s->op, "-=")) {
                        rhs = str_concat(str_concat(str_concat(str_concat(str_concat(vn, "_sub("), tgt), ", "), val), ")");
                    } else 
                    if (str_eq(s->op, "*=")) {
                        if (cg_is_vec_rt(s->value->rtype)) {
                            rhs = str_concat(str_concat(str_concat(str_concat(str_concat(vn, "_mul("), tgt), ", "), val), ")");
                        } else {
                            rhs = str_concat(str_concat(str_concat(str_concat(str_concat(vn, "_scale("), tgt), ", "), val), ")");
                        }
                    } else {
                        cg->had_error = true;
                    }
                    cg_out(cg, str_concat(str_concat(str_concat(str_concat(cg_indent(ind), tgt), " = "), rhs), ";\n"));
                } else {
                    cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent(ind), gen_expr(cg, s->target)), " "), s->op), " "), gen_expr(cg, s->value)), ";\n"));
                }
            }
            break;
        }
        case StIf:
        {
            cg_out(cg, str_concat(str_concat(str_concat(cg_indent(ind), "if "), paren_cond(gen_expr(cg, s->cond))), " "));
            gen_braced(cg, ind, s->then_block);
            if (s->else_branch != 0) {
                cg_out(cg, " else ");
                if (s->else_branch->kind == StIf) {
                    cg_out(cg, "\n");
                    gen_stmt(cg, ind, s->else_branch);
                } else {
                    gen_braced(cg, ind, s->else_branch);
                    cg_out(cg, "\n");
                }
            } else {
                cg_out(cg, "\n");
            }
            break;
        }
        case StWhile:
        {
            cg_out(cg, str_concat(str_concat(str_concat(cg_indent(ind), "while "), paren_cond(gen_expr(cg, s->cond))), " "));
            loop_enter(cg);
            gen_braced(cg, ind, s->body);
            cg_out(cg, "\n");
            cg_out(cg, loop_leave(cg, ind));
            break;
        }
        case StForIn:
        {
            if (((s->iter != 0) && (s->iter->kind == ExBinary)) && str_eq(s->iter->text, "..")) {
                const char* lo = gen_expr(cg, s->iter->a);
                const char* hi = gen_expr(cg, s->iter->b);
                cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent(ind), "for (int64_t "), s->name), " = "), lo), "; "), s->name), " < "), hi), "; "), s->name), "++) "));
                loop_enter(cg);
                gen_braced(cg, ind, s->body);
                cg_out(cg, "\n");
                cg_out(cg, loop_leave(cg, ind));
            } else 
            if (cg_is_dynarr_rt(s->iter->rtype)) {
                const char* elemc = cg_dynarr_elem(s->iter->rtype);
                const char* arrx = gen_expr(cg, s->iter);
                cg_out(cg, str_concat(str_concat(str_concat(cg_indent(ind), "{ Array _arr = "), arrx), ";\n"));
                cg_out(cg, str_concat(cg_indent((ind + 1)), "for (int64_t _i = 0; _i < _arr.len; _i++) {\n"));
                cg_out(cg, str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(cg_indent((ind + 2)), elemc), " "), s->name), " = (("), elemc), "*)_arr.data)[_i];\n"));
                loop_enter(cg);
                if ((s->body != 0) && (s->body->kind == StBlock)) {
                    for (int64_t i = 0; i < s->body->stmts.len; i++) {
                        gen_stmt(cg, (ind + 2), ((Stmt**)(s->body->stmts).data)[i]);
                    }
                }
                const char* label = loop_leave(cg, (ind + 1));
                cg_out(cg, str_concat(cg_indent((ind + 1)), "}\n"));
                cg_out(cg, label);
                cg_out(cg, str_concat(cg_indent(ind), "}\n"));
            } else {
                cg->had_error = true;
                cg_out(cg, str_concat(cg_indent(ind), "/* unsupported for-in iterable */\n"));
            }
            break;
        }
        case StSwitch:
        {
            cg_out(cg, str_concat(str_concat(str_concat(cg_indent(ind), "switch ("), gen_expr(cg, s->subject)), ") {\n"));
            cg->switch_depth += 1;
            for (int64_t i = 0; i < s->cases.len; i++) {
                SwitchCase sc = ((SwitchCase*)(s->cases).data)[i];
                if (sc.is_default) {
                    cg_out(cg, str_concat(cg_indent((ind + 1)), "default: {\n"));
                } else {
                    for (int64_t j = 0; j < sc.values.len; j++) {
                        cg_out(cg, str_concat(str_concat(str_concat(cg_indent((ind + 1)), "case "), gen_expr(cg, ((Expr**)(sc.values).data)[j])), ":\n"));
                    }
                    cg_out(cg, str_concat(cg_indent((ind + 1)), "{\n"));
                }
                if ((sc.body != 0) && (sc.body->kind == StBlock)) {
                    for (int64_t j = 0; j < sc.body->stmts.len; j++) {
                        gen_stmt(cg, (ind + 2), ((Stmt**)(sc.body->stmts).data)[j]);
                    }
                }
                cg_out(cg, str_concat(cg_indent((ind + 2)), "break;\n"));
                cg_out(cg, str_concat(cg_indent((ind + 1)), "}\n"));
            }
            cg->switch_depth -= 1;
            cg_out(cg, str_concat(cg_indent(ind), "}\n"));
            break;
        }
        case StRegion:
        {
            {
                const char* rname = s->name;
                if (str_len(rname) == 0) {
                    rname = "_region";
                    if (cg->regions.len > 0) {
                        rname = str_concat("_region", str_from_int((cg->regions.len + 1)));
                    }
                }
                cg_out(cg, str_concat(cg_indent(ind), "{\n"));
                cg_out(cg, str_concat(str_concat(str_concat(cg_indent((ind + 1)), "Arena "), rname), " = arena_make();\n"));
                ({ const char* _e = rname; arr_push(&(cg->regions), &_e); });
                if ((s->body != 0) && (s->body->kind == StBlock)) {
                    for (int64_t i = 0; i < s->body->stmts.len; i++) {
                        gen_stmt(cg, (ind + 1), ((Stmt**)(s->body->stmts).data)[i]);
                    }
                }
                cg->regions.len = (cg->regions.len - 1);
                cg_out(cg, str_concat(str_concat(str_concat(cg_indent((ind + 1)), "arena_free(&"), rname), ");\n"));
                cg_out(cg, str_concat(cg_indent(ind), "}\n"));
            }
            break;
        }
        default: {
            cg->had_error = true;
            break;
        }
    }
}

const char* func_sig(Decl* d) {
    const char* s = str_concat(str_concat(str_concat(ty_to_c(d->ret), " "), d->name), "(");
    if (d->params.len == 0) {
        s = str_concat(s, "void");
    } else {
        Array ps = ({ Array _a = arr_make(sizeof(const char*)); _a; });
        for (int64_t i = 0; i < d->params.len; i++) {
            ({ const char* _e = str_concat(str_concat(ty_to_c(((Param*)(d->params).data)[i].type), " "), ((Param*)(d->params).data)[i].name); arr_push(&(ps), &_e); });
        }
        s = str_concat(s, join_with(ps, ", "));
    }
    return str_concat(s, ")");
}

bool is_dll_export(Codegen* cg, Decl* d) {
    return ((cg->no_main && (d->module == 0)) && d->is_exported);
}

const char* export_prefix(Codegen* cg, Decl* d) {
    if (is_dll_export(cg, d)) {
        return "STRATA_EXPORT ";
    }
    return "";
}

void gen_includes(Codegen* cg, Program prog) {
    cg_out(cg, "#include <stdint.h>\n");
    cg_out(cg, "#include <stdbool.h>\n");
    cg_out(cg, "#include <stdio.h>\n");
    cg_out(cg, "#include <arena.h>\n");
    cg_out(cg, "#include <smath.h>\n");
    cg_out(cg, "#include <sstr.h>\n");
    cg_out(cg, "#include <sio.h>\n");
    cg_out(cg, "#include <sarr.h>\n");
    cg_out(cg, "#include <sprelude.h>\n");
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcInclude) {
            if (d->is_system) {
                cg_out(cg, str_concat(str_concat("#include <", d->path), ">\n"));
            } else {
                cg_out(cg, str_concat(str_concat("#include \"", d->path), "\"\n"));
            }
        }
    }
    if (cg->no_main) {
        cg_out(cg, "#ifdef _WIN32\n#define STRATA_EXPORT __declspec(dllexport)\n#else\n#define STRATA_EXPORT __attribute__((visibility(\"default\")))\n#endif\n");
    }
    cg_out(cg, "\n");
}

void gen_types(Codegen* cg, Program prog) {
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcEnum) {
            cg_out(cg, "typedef enum {");
            for (int64_t m = 0; m < d->members.len; m++) {
                if (m > 0) {
                    cg_out(cg, ",");
                }
                cg_out(cg, str_concat(" ", ((const char**)(d->members).data)[m]));
            }
            cg_out(cg, str_concat(str_concat(" } ", d->name), ";\n"));
        }
    }
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcStruct) {
            cg_out(cg, str_concat(str_concat(str_concat(str_concat("typedef struct ", d->name), " "), d->name), ";\n"));
        }
    }
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcStruct) {
            cg_out(cg, str_concat(str_concat("struct ", d->name), " {\n"));
            for (int64_t f = 0; f < d->fields.len; f++) {
                cg_out(cg, str_concat(str_concat(str_concat(str_concat("    ", ty_to_c(((FieldDef*)(d->fields).data)[f].type)), " "), ((FieldDef*)(d->fields).data)[f].name), ";\n"));
            }
            cg_out(cg, "};\n");
        }
    }
    cg_out(cg, "\n");
}

void gen_function(Codegen* cg, Decl* d, const char* prefix) {
    cg->ret_c = ty_to_c(d->ret);
    cg_out(cg, str_concat(str_concat(prefix, func_sig(d)), " "));
    gen_braced(cg, 0, d->body);
    cg_out(cg, "\n\n");
}

void gen_main(Codegen* cg, Program prog) {
    if (!cg->no_main) {
        cg->ret_c = "int";
        cg_out(cg, "int main(int strata_argc_, char** strata_argv_) {\n");
        cg_out(cg, "    strata_set_args(strata_argc_, strata_argv_);\n");
        for (int64_t i = 0; i < prog.main.len; i++) {
            gen_stmt(cg, 1, ((Stmt**)(prog.main).data)[i]);
        }
        cg_out(cg, "    return 0;\n}\n");
    }
}

const char* generate(Codegen* cg, Program prog) {
    cg_out(cg, "// Generated by stratac. Do not edit.\n");
    cg_out(cg, "#define STRATA_PROGRAM 1\n");
    gen_includes(cg, prog);
    gen_types(cg, prog);
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcFunc) {
            cg_out(cg, str_concat(str_concat(export_prefix(cg, d), func_sig(d)), ";\n"));
        }
    }
    cg_out(cg, "\n");
    for (int64_t i = 0; i < prog.decls.len; i++) {
        Decl* d = ((Decl**)(prog.decls).data)[i];
        if (d->kind == DcFunc) {
            gen_function(cg, d, export_prefix(cg, d));
        }
    }
    gen_main(cg, prog);
    return join_pieces(cg->parts);
}

const char* unit_name(int64_t m, const char* name) {
    const char* r = str_concat(str_concat("m", str_from_int(m)), "_");
    int64_t n = str_len(name);
    for (int64_t i = 0; i < n; i++) {
        char ch = name[i];
        if ((((ch >= 'a') && (ch <= 'z')) || ((ch >= 'A') && (ch <= 'Z'))) || ((ch >= '0') && (ch <= '9'))) {
            r = str_concat(r, str_sub(name, i, 1));
        } else {
            r = str_concat(r, "_");
        }
    }
    return str_concat(r, ".c");
}

SplitOutput generate_split(Codegen* cg, Program prog, const char* header_name, const char* guard) {
    cg->parts = no_parts();
    cg_out(cg, "// Generated by stratac. Do not edit.\n");
    cg_out(cg, str_concat(str_concat(str_concat(str_concat("#ifndef ", guard), "\n#define "), guard), "\n"));
    cg_out(cg, "#define STRATA_SPLIT 1\n");
    gen_includes(cg, prog);
    gen_types(cg, prog);
    cg_out(cg, "#endif\n");
    const char* header = join_pieces(cg->parts);
    Array names = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    Array units = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    for (int64_t m = 0; m < prog.modules.len; m++) {
        bool any = (m == 0);
        for (int64_t i = 0; i < prog.decls.len; i++) {
            if ((((Decl**)(prog.decls).data)[i]->module == m) && (((Decl**)(prog.decls).data)[i]->kind == DcFunc)) {
                any = true;
            }
        }
        if (any) {
            cg->parts = no_parts();
            cg_out(cg, str_concat(str_concat("// Generated by stratac from ", ((Module*)(prog.modules).data)[m].file), ". Do not edit.\n"));
            if (m == 0) {
                cg_out(cg, "#define STRATA_MAIN_TU 1\n#define STRATA_PROGRAM 1\n");
            }
            cg_out(cg, str_concat(str_concat("#include \"", header_name), "\"\n\n"));
            for (int64_t i = 0; i < prog.decls.len; i++) {
                Decl* d = ((Decl**)(prog.decls).data)[i];
                if (((d->kind == DcFunc) && d->is_exported) && ((d->module == m) || module_sees(prog, m, d->module))) {
                    cg_out(cg, str_concat(str_concat(export_prefix(cg, d), func_sig(d)), ";\n"));
                }
            }
            for (int64_t i = 0; i < prog.decls.len; i++) {
                Decl* d = ((Decl**)(prog.decls).data)[i];
                if (((d->module == m) && (d->kind == DcFunc)) && (!d->is_exported)) {
                    cg_out(cg, str_concat(str_concat("static ", func_sig(d)), ";\n"));
                }
            }
            cg_out(cg, "\n");
            for (int64_t i = 0; i < prog.decls.len; i++) {
                Decl* d = ((Decl**)(prog.decls).data)[i];
                if ((d->module == m) && (d->kind == DcFunc)) {
                    if (d->is_exported) {
                        gen_function(cg, d, export_prefix(cg, d));
                    } else {
                        gen_function(cg, d, "static ");
                    }
                }
            }
            if (m == 0) {
                gen_main(cg, prog);
            }
            ({ const char* _e = unit_name(m, ((Module*)(prog.modules).data)[m].name); arr_push(&(names), &_e); });
            ({ const char* _e = join_pieces(cg->parts); arr_push(&(units), &_e); });
        }
    }
    return (SplitOutput){header, names, units};
}

bool module_sees(Program prog, int64_t m, int64_t v) {
    Module mod = ((Module*)(prog.modules).data)[m];
    for (int64_t i = 0; i < mod.visible.len; i++) {
        if (((int64_t*)(mod.visible).data)[i] == v) {
            return true;
        }
    }
    return false;
}

Array no_parts(void) {
    Array p = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    return p;
}

bool header_uses_math(TypeNode* t) {
    if (t == 0) {
        return false;
    }
    if (t->kind != TyNamed) {
        return header_uses_math(t->elem);
    }
    return ((((str_eq(t->name, "vec2") || str_eq(t->name, "vec3")) || str_eq(t->name, "vec4")) || str_eq(t->name, "mat4")) || str_eq(t->name, "quat"));
}

bool header_uses_array(TypeNode* t) {
    if (t == 0) {
        return false;
    }
    if (t->kind == TyDynArray) {
        return true;
    }
    return header_uses_array(t->elem);
}

