bool ends_with(const char* s, const char* suffix) {
    return ((str_len(s) >= str_len(suffix)) && str_eq(str_sub(s, (str_len(s) - str_len(suffix)), str_len(suffix)), suffix));
}

Project no_project(void) {
    Array e = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    return (Project){false, "", "", "", "", "", "", "", false, e, e, e, e, e, e, false};
}

Target resolve_target(const char* arg) {
    if (ends_with(arg, ".strata") || ends_with(arg, ".str")) {
        return (Target){true, false, arg, no_project()};
    }
    const char* toml = "strata.toml";
    if (ends_with(arg, "strata.toml")) {
        toml = arg;
    } else 
    if (!str_eq(arg, "")) {
        toml = str_concat(arg, "/strata.toml");
    }
    if (!file_present(toml)) {
        if (str_eq(arg, "")) {
            strata_report("error: no strata.toml in this folder (pass a .strata file or a project folder, or create one with 'stratac new <name>')");
        } else {
            strata_report(str_concat("error: no strata.toml in ", arg));
        }
        return (Target){false, false, "", no_project()};
    }
    Project p = load_project(toml);
    return (Target){p.ok, true, str_concat(str_concat(p.root, "/"), p.entry), p};
}

BuildSpec target_spec(Target t, const char* version, bool release, bool force, bool quiet) {
    if (t.is_project) {
        return spec_for_project(t.proj, version, release, force, quiet);
    }
    return spec_for_file(t.file, version, quiet);
}

const char* stratac_version(void) {
    return "1.6.0 (cross-platform)";
}

bool file_exists(const char* p) {
    return (str_len(strata_read_file(p)) > 0);
}

const char* resolve_libdir(const char* argv0) {
    const char* exe = strata_exe_path();
    if (!str_eq(exe, "")) {
        const char* edir = dirname_of(exe);
        if (file_exists(str_concat(edir, "/lib/arena.h"))) {
            return str_concat(edir, "/lib");
        }
        if (file_exists(str_concat(edir, "/../lib/arena.h"))) {
            return str_concat(edir, "/../lib");
        }
    }
    const char* dir = dirname_of(argv0);
    if (file_exists(str_concat(dir, "/lib/arena.h"))) {
        return str_concat(dir, "/lib");
    }
    if (file_exists(str_concat(dir, "/../lib/arena.h"))) {
        return str_concat(dir, "/../lib");
    }
    if (file_exists("lib/arena.h")) {
        return "lib";
    }
    if (file_exists("../lib/arena.h")) {
        return "../lib";
    }
    return str_concat(dir, "/lib");
}

